replacements.new:
function bool IsVersusFreeLookDetached()
{
    return IsLocalViewportPlayer() && bVersusFreeLookActive;
}

function bool ShouldCouplePawnRotationToCamera()
{
    return !IsVersusFreeLookDetached();
}

function rotator GetScreenRelativeMovementRotation()
{
    if (IsVersusFreeLookDetached())
        return VersusFreeLookPawnRotation;

    return Super.GetScreenRelativeMovementRotation();
}

function BeginVersusFreeLook()
{
    if (!IsLocalViewportPlayer() || bVersusDead)
        return;

    bVersusFreeLookActive = True;
    VersusFreeLookPawnRotation = Rotation;
    VersusFreeLookPawnRotation.Pitch = 0;
    VersusFreeLookPawnRotation.Roll = 0;

    if (Cam != None)
    {
        VersusFreeLookAimRotation = Cam.rCurrRotation;
        // StateStandardCam already rotates and positions the camera around
        // CamTarget. Alt only stops the pawn from following that yaw.
        Cam.bSyncPositionWithTarget = True;
        Cam.bSyncRotationWithTarget = False;
        Cam.rExtraRotation = rot(0,0,0);
        VersusFreeLookLastCamLocation = Cam.Location;
        NextVersusFreeLookViewLogTime = 0.0;
    }
    else
        VersusFreeLookAimRotation = ViewRotation;

    VersusFreeLookAimRotation.Yaw = VersusFreeLookPawnRotation.Yaw;
    VersusFreeLookAimRotation.Roll = 0;
    Log("HPV FREELOOK ENTER pawn=" $ string(self)
        $ " pawnYaw=" $ string(VersusFreeLookPawnRotation.Yaw));
}

function EndVersusFreeLook()
{
    // Restore the unchanged pawn first, then use the stock snap exactly once
    // to put the camera behind that yaw. No orbit math is duplicated here.
    ViewRotation = VersusFreeLookAimRotation;
    ViewRotation.Yaw = VersusFreeLookPawnRotation.Yaw;
    DesiredRotation = VersusFreeLookPawnRotation;
    SetRotation(VersusFreeLookPawnRotation);

    if (Cam != None)
    {
        Cam.rExtraRotation = rot(0,0,0);
        Cam.InitPositionAndRotation(True);
        ViewRotation = Cam.Rotation;
    }

    bVersusFreeLookActive = False;
    NextVersusFreeLookViewLogTime = 0.0;
    if (Cam != None)
        Log("HPV FREELOOK EXIT pawn=" $ string(self)
            $ " camLocation=" $ string(Cam.Location));
    else
        Log("HPV FREELOOK EXIT pawn=" $ string(self) $ " cam=None");
}

function ResetVersusFreeLook(string Reason)
{
    if (!IsLocalViewportPlayer())
        return;

    if (bVersusFreeLookActive)
        Log("HPV FREELOOK RESET pawn=" $ string(self) $ " reason=" $ Reason);
    bVersusFreeLook = 0;
    bVersusFreeLookActive = False;
    NextVersusFreeLookViewLogTime = 0.0;
}

function UpdateVersusFreeLook()
{
    if (!IsLocalViewportPlayer() || bVersusDead)
        return;

    if (bVersusFreeLook == 0)
    {
        if (bVersusFreeLookActive)
            EndVersusFreeLook();
        return;
    }

    if (!bVersusFreeLookActive)
        BeginVersusFreeLook();

    // Freeze only body/view authority. BaseCam's normal standard-camera
    // tick consumes the mouse and orbits around its attached CamTarget.
    ViewRotation = VersusFreeLookAimRotation;
    DesiredRotation = VersusFreeLookPawnRotation;
    SetRotation(VersusFreeLookPawnRotation);
    aTurn = 0.0;
}

exec function VersusFreeLookState()
{
    ClientMessage("Free Look: held=" $ string(bVersusFreeLook != 0)
        $ " active=" $ string(bVersusFreeLookActive));
    Log("HPV FREELOOK STATE pawn=" $ string(self)
        $ " held=" $ string(bVersusFreeLook != 0)
        $ " active=" $ string(bVersusFreeLookActive)
        $ " pawnRotation=" $ string(Rotation)
        $ " viewRotation=" $ string(ViewRotation)
        $ " cameraRotation=" $ string(Cam.Rotation));
}

event PlayerCalcView(out Actor ViewActor, out Vector CameraLocation, out Rotator CameraRotation)
{
    Super.PlayerCalcView(ViewActor, CameraLocation, CameraRotation);

    if (!bVersusFreeLookActive || Cam == None)
        return;
    if (Level.TimeSeconds < NextVersusFreeLookViewLogTime)
        return;

    NextVersusFreeLookViewLogTime = Level.TimeSeconds + 0.20;
    Log("HPV FREELOOK VIEW time=" $ string(Level.TimeSeconds)
        $ " ViewTarget=" $ string(ViewTarget)
        $ " Cam=" $ string(Cam)
        $ " ViewTargetEqualsCam=" $ string(ViewTarget == Cam)
        $ " CamState=" $ string(Cam.GetStateName())
        $ " PlayerCalcView.CameraLocation=" $ string(CameraLocation)
        $ " PlayerCalcView.CameraRotation=" $ string(CameraRotation)
        $ " CameraLocationMinusCam=" $ string(VSize(CameraLocation - Cam.Location)));
    Log("HPV FREELOOK CAM Cam.Location=" $ string(Cam.Location)
        $ " Cam.LocationDelta=" $ string(VSize(Cam.Location - VersusFreeLookLastCamLocation))
        $ " Cam.Rotation=" $ string(Cam.Rotation)
        $ " Cam.rDestRotation=" $ string(Cam.rDestRotation)
        $ " Cam.rCurrRotation=" $ string(Cam.rCurrRotation)
        $ " Cam.bSyncPositionWithTarget=" $ string(Cam.bSyncPositionWithTarget));
    if (Cam.CamTarget != None)
        Log("HPV FREELOOK TARGET Cam.CamTarget=" $ string(Cam.CamTarget)
            $ " Cam.CamTarget.Location=" $ string(Cam.CamTarget.Location)
            $ " Cam.CamTarget.Rotation=" $ string(Cam.CamTarget.Rotation)
            $ " CamDistance=" $ string(VSize(Cam.Location - Cam.CamTarget.Location)));
    else
        Log("HPV FREELOOK TARGET Cam.CamTarget=None");
    Log("HPV FREELOOK PAWN Rotation=" $ string(Rotation)
        $ " DesiredRotation=" $ string(DesiredRotation)
        $ " ViewRotation=" $ string(ViewRotation)
        $ " bScreenRelativeMovement=" $ string(bScreenRelativeMovement));
    VersusFreeLookLastCamLocation = Cam.Location;
}

